public class InnerSourceEndpointStandardSourceEndpointNetworkingConfigurationFactory(Action<Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointNetworkingConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointNetworkingConfiguration>
{

    internal InnerSourceEndpointVpcSourceEndpointNetworkingConfigurationFactory VpcFactory { get; set; }

    internal InnerSourceEndpointPublicSourceEndpointNetworkingConfigurationFactory PublicFactory { get; set; }

    protected override Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointNetworkingConfiguration Create()
    {
        var standardSourceEndpointNetworkingConfigurationResult = CreateStandardSourceEndpointNetworkingConfiguration();
        factoryAction?.Invoke(standardSourceEndpointNetworkingConfigurationResult);

        return standardSourceEndpointNetworkingConfigurationResult;
    }

    private Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointNetworkingConfiguration CreateStandardSourceEndpointNetworkingConfiguration()
    {
        var standardSourceEndpointNetworkingConfigurationResult = new Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointNetworkingConfiguration();

        return standardSourceEndpointNetworkingConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaConnect.SourceEndpointTypes.StandardSourceEndpointNetworkingConfiguration result)
    {
        base.CreateChildren(result);

        result.Vpc ??= VpcFactory?.Build();
        result.Public ??= PublicFactory?.Build();
    }

} // End Of Class

